def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos_like(x):
        return isinstance(x, (list, tuple)) and len(x) >= 2

    def get_pos(obj, key):
        v = obj.get(key)
        if pos_like(v):
            return v[0], v[1]
        return None

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_list(v):
        return v if isinstance(v, list) else []

    env = observation.get("environment_name") or "resource_collection"
    self_pos = get_pos(observation, "self_position")
    if self_pos is None:
        self_pos = (0, 0)
    opp_pos = get_pos(observation, "opponent_position")
    if opp_pos is None:
        opp_pos = self_pos

    gw = observation.get("grid_width")
    gh = observation.get("grid_height")
    if not isinstance(gw, int) or gw <= 0:
        gw = 7
    if not isinstance(gh, int) or gh <= 0:
        gh = 7

    role = observation.get("self_role") or "pursuer"

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        target = corners[0]
        best = -1
        for c in corners:
            d = manhattan(c, opp_pos)
            if d > best:
                best = d
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells"))
        if not targets:
            targets = safe_list(observation.get("opponent_territory"))
        if not targets:
            targets = safe_list(observation.get("neutral_cells"))
        if targets:
            best_t = None
            best_d = None
            for t in targets:
                if pos_like(t):
                    p = (t[0], t[1])
                    d = manhattan(self_pos, p)
                    if best_d is None or d < best_d:
                        best_d = d
                        best_t = p
            if best_t is not None:
                return step_toward(self_pos, best_t)
        return [0, 0]

    resources = safe_list(observation.get("resources"))
    if resources:
        best_r = None
        best_d = None
        for r in resources:
            if pos_like(r):
                p = (r[0], r[1])
                d = manhattan(self_pos, p)
                if best_d is None or d < best_d:
                    best_d = d
                    best_r = p
        if best_r is not None:
            return step_toward(self_pos, best_r)

    # Denial / fallback: move toward opponent if close, else toward center-ish area.
    if manhattan(self_pos, opp_pos) <= 3:
        return step_toward(self_pos, opp_pos)

    center = (gw // 2, gh // 2)
    return step_toward(self_pos, center)

